FUNCTION_BLOCK FB_Pharma_CoreSheathCoExtrusion
(*
========================================================================================================================
  PROJECT      : PHARMACEUTICAL CONTINUOUS MANUFACTURING & SOLID DISPERSION CO-EXTRUSION SUITE
  SUBSYSTEM    : CONCENTRIC CORE-SHEATH DUAL-POLYMER HOT-MELT MICRO-CO-EXTRUSION (HME-FDC)
  MODULE       : DUAL-POLYMER MELT VISCOSITY BALANCING & MICRO-DIE THERMAL SEGREGATION CONTROLLER
  CLASSIFICATION: SIL-2 / cGMP 21 CFR PART 11 / EN ISO 13849-1 PL-d DUAL TRAIN CONTROL SYSTEM
  SPECIFICATION: IEC 61131-3 3RD EDITION / ISA-88 PROCEDURAL STATES / ISA-18.2 INDUSTRIAL ALARM MGMT
  ENGINEER     : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  CYBER-PHYSICAL SYSTEM ARCHITECTURE & PHENOMENOLOGICAL FORMULATION:

  1. CONCENTRIC MULTI-STREAM CONTINUOUS HOT-MELT MICRO-CO-EXTRUSION:
     Hot-melt co-extrusion allows one-step fabrication of concentric core-sheath drug delivery matrices.
     - CORE STREAM   : Thermosensitive active pharmaceutical ingredient (API, e.g. Ritonavir / Fenofibrate)
                       molecularly dispersed into an amphiphilic copolymer carrier matrix (Kollidon VA64 / Soluplus).
                       Core processing thermal ceiling is capped strictly at 138.0 deg C to prevent irreversible
                       thermal decomposition / degradation of the active substance.
     - SHEATH STREAM : Functional release-rate modifying barrier / enteric polymer (Eudragit RL/RS, Ethylcellulose
                       with Triethyl Citrate plasticizer), requiring processing temperatures of 172.0 - 176.0 deg C
                       to ensure full polymer chain disentanglement, homogeneous plasticization, and defect-free melt flow.

  2. MICRO-DIE THERMAL SEGREGATION & 1-D CONJUGATE HEAT TRANSFER:
     The concentric die body merges the core and sheath polymer melts at a sub-millimeter annular orifice:
         Core Mandrel Orifice Diameter (d_core_out) = 1.20 mm, Wall Thickness = 0.20 mm.
         Sheath Outer Die Annulus (D_die_exit)      = 2.40 mm.
     The steady-state temperature gradient between the sheath annulus (175.0 deg C) and core pin (135.0 deg C)
     is 40.0 deg C across a radial distance of only delta_r = 0.35 mm (temperature gradient > 114 K/mm).
     Micro-die thermal segregation employs a high-temperature engineered ceramic insulating sleeve (Zirconia ZrO2,
     thermal conductivity k_ins = 2.0 W/m.K) paired with localized micro-cartridge thermal guard zones.
     Uncompensated thermal conduction causes core overheating (inducing API degradation) or sheath premature chilling
     (inducing flow stagnation, high die pressure surges, and die freeze-up).

  3. NON-NEWTONIAN POLYMER MELT RHEOLOGY & VISCOSITY RATIO EQUILIBRIUM:
     Both polymer melts exhibit pseudoplastic shear-thinning behavior governed by the Cross rheological model:
         eta(gamma_dot, T) = eta_0(T) / [ 1 + (lambda * gamma_dot)^(1 - n) ]
     with Arrhenius temperature-dependent zero-shear viscosity shift:
         eta_0(T) = A_0 * exp( E_a / (R * (T + 273.15)) )
     Where:
         gamma_dot_core   = 4 * Q_vol_core / (PI * R_core^3)        [s^-1]
         gamma_dot_sheath = 6 * Q_vol_sheath / (PI * (R_out + R_in) * (R_out - R_in)^2) [s^-1]
     At the confluence plane, if the dynamic viscosity ratio:
         R_eta = eta_core / eta_sheath
     diverges from unity (acceptable envelope: 0.85 <= R_eta <= 1.18), interfacial hydrodynamic instability
     triggers "viscosity encapsulation" (the lower viscosity stream encapsulates the higher viscosity stream,
     collapsing concentricity) or severe interfacial wave distortion, leading to variable drug dissolution kinetics.

  4. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ARCHITECTURE:
     Three redundant piezo-resistive melt pressure transducers (PT1, PT2, PT3) measure the core melt pump discharge
     pressure directly upstream of the micro-die. The 2oo3 voter executes online discrepancy monitoring, dynamically
     ejecting faulty or drifting transmitters (|Delta P| > 3.5 bar), degrading smoothly from 2oo3 to 2oo2, then to
     1oo1 with high-priority maintenance alerts, before triggering safe depressurization upon complete sensor loss.

  5. DISCRETE MULTIVARIABLE STATE-SPACE MODEL PREDICTIVE CONTROL (MPC):
     The plant is modeled by a 4-state, 4-input discrete-time state-space representation (Ts = 50 ms):
         x(k+1) = A_sys * x(k) + B_sys * u(k) + d(k)
         y(k)   = C_sys * x(k)
     State Vector:
         x1 = Delta_P_core       : Core melt pressure tracking deviation [bar]
         x2 = Delta_P_sheath     : Sheath melt pressure tracking deviation [bar]
         x3 = ln(R_eta)          : Logarithmic viscosity ratio error [dimensionless]
         x4 = Delta_T_seg        : Micro-die thermal segregation barrier deviation [deg C]
     Manipulated Input Vector:
         u1 = Delta_N_pump_core  : Precision gear pump core speed trim [rpm]
         u2 = Delta_N_pump_sheath: Precision gear pump sheath speed trim [rpm]
         u3 = Delta_Q_die_heat   : Sheath annular die zone heater duty cycle [%]
         u4 = Delta_Q_barrier    : Thermal segregation active cooling/guard duty cycle [%]
========================================================================================================================
*)

VAR_INPUT
    (* --- Master Permissives & cGMP Operational Modes --- *)
    bMasterEnable                   : BOOL;     (* Master process train enable permissive [TRUE=Permitted] *)
    bSafetyInterlockOk              : BOOL;     (* Hardwired PL-d emergency stop / die safety loop [TRUE=Healthy] *)
    bAutoMpcEnable                  : BOOL;     (* Supervisory mode: TRUE = Full Closed-Loop MPC, FALSE = Safe Coordinated *)
    bBatchRunPermissive             : BOOL;     (* MES / SCADA recipe active and validated for 21 CFR Part 11 batch *)

    (* --- Redundant Pressure Transducers: Core Extruder Confluence (2oo3 TMR) --- *)
    rCorePressure_PT1_bar           : REAL;     (* Core melt pressure sensor channel 1 [bar] (0.0 .. 350.0) *)
    rCorePressure_PT2_bar           : REAL;     (* Core melt pressure sensor channel 2 [bar] (0.0 .. 350.0) *)
    rCorePressure_PT3_bar           : REAL;     (* Core melt pressure sensor channel 3 [bar] (0.0 .. 350.0) *)

    (* --- Sheath & Micro-Die Pressures --- *)
    rSheathPressure_bar             : REAL;     (* Sheath gear pump discharge pressure [bar] (0.0 .. 350.0) *)
    rDieConfluencePressure_bar      : REAL;     (* Downstream micro-die exit confluence pressure [bar] (0.0 .. 250.0) *)

    (* --- Process Thermal Analytics & Profile Sensors --- *)
    rCoreMeltTemp_DegC              : REAL;     (* Core polymer melt temperature before confluence [deg C] (80.0 .. 200.0) *)
    rSheathMeltTemp_DegC            : REAL;     (* Sheath polymer melt temperature before confluence [deg C] (120.0 .. 240.0) *)
    rDieThermalBarrierTemp_DegC     : REAL;     (* Micro-die insulation barrier thermocouple [deg C] (100.0 .. 220.0) *)
    rCoreDiePinTemp_DegC            : REAL;     (* Core internal mandrel micro-tip temperature [deg C] (100.0 .. 180.0) *)
    rSheathOuterDieTemp_DegC        : REAL;     (* Sheath outer die body thermal collar temp [deg C] (130.0 .. 220.0) *)

    (* --- Extruder Drive & Dosing Telemetry --- *)
    rCoreExtruderScrewSpeed_rpm     : REAL;     (* Core co-rotating twin-screw drive speed [rpm] (0.0 .. 300.0) *)
    rSheathExtruderScrewSpeed_rpm   : REAL;     (* Sheath twin-screw drive speed [rpm] (0.0 .. 300.0) *)
    rCoreExtruderTorque_Nm          : REAL;     (* Core twin-screw motor drive torque [Nm] (0.0 .. 120.0) *)
    rSheathExtruderTorque_Nm        : REAL;     (* Sheath twin-screw motor drive torque [Nm] (0.0 .. 120.0) *)
    rCoreGravimetricFeed_gpmin      : REAL;     (* Core loss-in-weight feeder mass flow rate [g/min] (0.5 .. 100.0) *)
    rSheathGravimetricFeed_gpmin    : REAL;     (* Sheath loss-in-weight feeder mass flow rate [g/min] (1.0 .. 250.0) *)
    rLinePullerSpeed_mpmin          : REAL;     (* Downstream caterpillar haul-off line speed [m/min] (0.1 .. 20.0) *)
END_VAR

VAR_OUTPUT
    (* --- System Readiness & Operational Mode Indicators --- *)
    bSystemReady                    : BOOL;     (* Overall co-extrusion cell operational permissive *)
    bDegradedModeActive             : BOOL;     (* Operating under degraded sensor or actuator constraint *)
    bViscosityBalanced              : BOOL;     (* Melt viscosity ratio within critical stability window *)
    bThermalSegregationOk           : BOOL;     (* Thermal segregation gradient across micro-die within spec *)

    (* --- Actuator Commands & Direct Drive Setpoints --- *)
    rCoreMeltPumpSpeed_rpm          : REAL;     (* Core positive-displacement gear pump speed [rpm] (0.0 .. 60.0) *)
    rSheathMeltPumpSpeed_rpm        : REAL;     (* Sheath positive-displacement gear pump speed [rpm] (0.0 .. 60.0) *)
    rDieThermalSegregationHeat_Pct  : REAL;     (* Micro-die barrier guard heater modulation duty cycle [%] (0.0 .. 100.0) *)
    rCoreDieHeaterPower_Pct         : REAL;     (* Core mandrel internal heating power duty cycle [%] (0.0 .. 100.0) *)
    rSheathDieHeaterPower_Pct       : REAL;     (* Sheath outer annular ring heating power duty cycle [%] (0.0 .. 100.0) *)
    rMicroAirCoolingValve_Pct       : REAL;     (* Micro-die thermal segregation vortex air cooling pulse [%] (0.0 .. 100.0) *)

    (* --- Validated Process Telemetry & Rheological Metrics --- *)
    rVotedCorePressure_bar          : REAL;     (* 2oo3 TMR resolved validated core melt pressure [bar] *)
    rEstimatedViscosityRatio        : REAL;     (* Dynamic calculated Core/Sheath viscosity ratio (target: 1.00) *)
    rCoreSheathThermalDelta_DegC    : REAL;     (* Real-time measured thermal gradient across micro-die [deg C] *)
    rCoreResidenceTime_s            : REAL;     (* Calculated mean residence time in core hot zone [s] *)

    (* --- Diagnostics, Status & Audit Trail Registers --- *)
    wAlarmWord                      : WORD;     (* ISA-18.2 packed alarm status word *)
    wSystemStatusWord               : WORD;     (* Machine operational sub-state status register *)
    udiCgmpAuditTrailCounter        : UDINT;    (* Monotonic cycle counter for 21 CFR Part 11 audit tracing *)
END_VAR

VAR
    (* --- State Machine Registers --- *)
    iState                          : INT := 0; (* Active finite state machine state *)
    iPrevState                      : INT := 0; (* Historical state transition tracker *)

    (* --- 2oo3 Triple Modular Redundancy (TMR) Pressure Validation --- *)
    bPt1_Valid                      : BOOL := TRUE;
    bPt2_Valid                      : BOOL := TRUE;
    bPt3_Valid                      : BOOL := TRUE;
    iHealthySensorCount             : INT  := 3;
    rDeltaP12                       : REAL := 0.0;
    rDeltaP23                       : REAL := 0.0;
    rDeltaP31                       : REAL := 0.0;
    rTmrToleranceLimit_bar          : REAL := 3.50; (* Max permissible inter-sensor discrepancy [bar] *)

    (* --- Digital Signal Filtering & Condition Accumulators --- *)
    rCorePress_Filt                 : REAL := 0.0;
    rSheathPress_Filt               : REAL := 0.0;
    rCoreTemp_Filt                  : REAL := 0.0;
    rSheathTemp_Filt                : REAL := 0.0;
    rBarrierTemp_Filt               : REAL := 0.0;

    (* --- Rheological Modeling Parameters (Cross / Arrhenius Constants) --- *)
    (* Core Formulation: Soluplus / Kollidon VA64 + API *)
    rCore_Eta0_Ref                  : REAL := 1850.0;   (* Zero-shear viscosity at T_ref [Pa.s] *)
    rCore_Tref_K                    : REAL := 408.15;   (* Reference temperature = 135 deg C [K] *)
    rCore_Ea_Over_R                 : REAL := 4250.0;   (* Activation energy parameter E_a / R [K] *)
    rCore_Cross_Lambda              : REAL := 0.085;    (* Cross relaxation time constant [s] *)
    rCore_PowerLaw_n                : REAL := 0.420;    (* Pseudoplastic shear-thinning index [-] *)

    (* Sheath Formulation: Eudragit RL100 / Ethylcellulose + Plasticizer *)
    rSheath_Eta0_Ref                : REAL := 2400.0;   (* Zero-shear viscosity at T_ref [Pa.s] *)
    rSheath_Tref_K                  : REAL := 448.15;   (* Reference temperature = 175 deg C [K] *)
    rSheath_Ea_Over_R               : REAL := 5100.0;   (* Activation energy parameter E_a / R [K] *)
    rSheath_Cross_Lambda            : REAL := 0.115;    (* Cross relaxation time constant [s] *)
    rSheath_PowerLaw_n              : REAL := 0.380;    (* Pseudoplastic shear-thinning index [-] *)

    (* Rheological Calculation Working Variables *)
    rCoreTemp_K                     : REAL := 0.0;
    rSheathTemp_K                   : REAL := 0.0;
    rCore_ShiftFactor               : REAL := 1.0;
    rSheath_ShiftFactor             : REAL := 1.0;
    rCoreShearRate_s1               : REAL := 10.0;
    rSheathShearRate_s1             : REAL := 10.0;
    rCoreViscosity_Pas              : REAL := 1000.0;
    rSheathViscosity_Pas            : REAL := 1000.0;

    (* --- Micro-Die Geometry Constants --- *)
    rCoreOrificeRadius_m            : REAL := 0.00040;  (* 0.80 mm inner diameter pin / 2 *)
    rSheathAnnulusGap_m             : REAL := 0.00045;  (* Annular gap width [m] *)
    rSheathMeanRadius_m             : REAL := 0.00095;  (* Annular mean radius [m] *)
    rPolymerDensity_kgm3            : REAL := 1150.0;   (* Approximate melt density [kg/m3] *)

    (* --- State-Space Discrete Model Representation (Ts = 0.050 s) --- *)
    (* State Vector:
         x[0] = Delta_P_core   (deviation from target 95.0 bar)
         x[1] = Delta_P_sheath (deviation from target 110.0 bar)
         x[2] = ln(R_eta)      (deviation from target ln(1.0) = 0.0)
         x[3] = Delta_T_seg    (deviation from target 38.0 deg C gradient)
    *)
    rX_State1_CorePErr              : REAL := 0.0;
    rX_State2_SheathPErr            : REAL := 0.0;
    rX_State3_ViscLogErr            : REAL := 0.0;
    rX_State4_ThermalGradErr        : REAL := 0.0;

    (* Discrete State Transition Matrix A (4x4) *)
    rA11 : REAL := 0.9650; rA12 : REAL := 0.0120; rA13 : REAL := 0.0450; rA14 : REAL := -0.0080;
    rA21 : REAL := 0.0150; rA22 : REAL := 0.9580; rA23 : REAL := -0.0620; rA24 : REAL := 0.0110;
    rA31 : REAL := 0.0008; rA32 : REAL := -0.0009; rA33 : REAL := 0.9250; rA34 : REAL := -0.0210;
    rA41 : REAL := 0.0000; rA42 : REAL := 0.0000; rA43 : REAL := 0.0000; rA44 : REAL := 0.9820;

    (* Input Authority Matrix B (4x4) *)
    rB11 : REAL := 1.2500; rB12 : REAL := 0.0350; rB13 : REAL := -0.0150; rB14 : REAL := 0.0000;
    rB21 : REAL := 0.0400; rB22 : REAL := 1.4200; rB23 : REAL := -0.0220; rB24 : REAL := 0.0000;
    rB31 : REAL := 0.0045; rB32 : REAL := -0.0052; rB33 : REAL := -0.0085; rB34 : REAL := 0.0032;
    rB41 : REAL := 0.0000; rB42 : REAL := 0.0000; rB43 : REAL := 0.1250; rB44 : REAL := -0.1650;

    (* Model Predictive Feedback Control Matrix K_mpc (4x4, derived via LQR / QP synthesis) *)
    rK11 : REAL := 0.3850; rK12 : REAL := 0.0110; rK13 : REAL := 8.4500; rK14 : REAL := -0.0520;
    rK21 : REAL := 0.0120; rK22 : REAL := 0.4120; rK23 : REAL := -9.1500; rK24 : REAL := 0.0650;
    rK31 : REAL := -0.0250; rK32 : REAL := 0.0450; rK33 : REAL := -12.500; rK34 : REAL := 2.4500;
    rK41 : REAL := 0.0100; rK42 : REAL := -0.0180; rK43 : REAL := 4.2000; rK44 : REAL := -3.1500;

    (* MPC Optimal Control Increments *)
    rDeltaU1_CorePump               : REAL := 0.0;
    rDeltaU2_SheathPump             : REAL := 0.0;
    rDeltaU3_SheathDieHeat          : REAL := 0.0;
    rDeltaU4_BarrierAirCool         : REAL := 0.0;

    (* Setpoints & Operating Baselines *)
    rCorePressureSetpoint_bar       : REAL := 95.0;
    rSheathPressureSetpoint_bar     : REAL := 110.0;
    rTargetViscosityRatio           : REAL := 1.00;
    rTargetThermalSegregation_DegC  : REAL := 38.0; (* Required delta-T across barrier [deg C] *)
    rCorePumpNominal_rpm            : REAL := 18.5;
    rSheathPumpNominal_rpm          : REAL := 24.2;
    rSheathDieHeatNominal_Pct       : REAL := 62.0;
    rBarrierAirNominal_Pct          : REAL := 25.0;

    (* Execution Timers *)
    tonStartupSoak                  : TON;
    tonMeltStabilization            : TON;
    tonViscosityFaultDebounce       : TON;
    tonThermalFaultDebounce         : TON;
    tonWatchdog                     : TON;

    (* Historical Metrics & Safety Accumulators *)
    udiViscosityViolationCycles     : UDINT := 0;
    udiThermalViolationCycles       : UDINT := 0;
    rPeakCoreMeltTempRecorded_DegC  : REAL := 0.0;
END_VAR

(*
========================================================================================================================
  CYCLIC ALGORITHMIC EXECUTION PIPELINE
========================================================================================================================
*)

udiCgmpAuditTrailCounter := udiCgmpAuditTrailCounter + 1;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: HARDWIRED SAFETY PERMISSIVES & THERMAL OVER-TEMPERATURE API PROTECTION
   --------------------------------------------------------------------------------------------------------------------- *)
IF NOT bSafetyInterlockOk THEN
    (* Fail-Safe Emergency Shutdown: Stop All High-Pressure Positive-Displacement Pumps *)
    bSystemReady                    := FALSE;
    bDegradedModeActive             := FALSE;
    bViscosityBalanced              := FALSE;
    bThermalSegregationOk           := FALSE;
    rCoreMeltPumpSpeed_rpm          := 0.0;
    rSheathMeltPumpSpeed_rpm        := 0.0;
    rCoreDieHeaterPower_Pct         := 0.0;
    rSheathDieHeaterPower_Pct       := 0.0;
    rDieThermalSegregationHeat_Pct  := 0.0;
    rMicroAirCoolingValve_Pct       := 100.0; (* Full cooling to quench thermal runaway *)
    wAlarmWord.0                    := TRUE;  (* E-Stop / Safety Interlock Open *)
    wSystemStatusWord               := 16#F000;
    iState                          := 99;    (* Transition to emergency trip *)
    RETURN;
END_IF;

wAlarmWord.0 := FALSE;

(* API Thermal Degradation Immediate Interlock: Core Melt Temperature Capped at 142.0 deg C *)
IF rCoreMeltTemp_DegC >= 142.0 THEN
    wAlarmWord.1 := TRUE; (* API Thermal Degradation Risk Detected *)
    rCoreDieHeaterPower_Pct := 0.0;
    rMicroAirCoolingValve_Pct := 80.0;
    IF rCoreMeltTemp_DegC >= 145.0 THEN
        (* Catastrophic Drug Decomposition Limit Reached - Trip Core Extruder Feed *)
        bSystemReady           := FALSE;
        rCoreMeltPumpSpeed_rpm := 0.0;
        iState                 := 99;
        RETURN;
    END_IF;
ELSE
    wAlarmWord.1 := FALSE;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ALGORITHM FOR CORE PRESSURE
   --------------------------------------------------------------------------------------------------------------------- *)
(* Verify hardware instrument limits (piezo-resistive range: 1.0 to 320.0 bar) *)
bPt1_Valid := (rCorePressure_PT1_bar >= 1.0) AND (rCorePressure_PT1_bar <= 320.0);
bPt2_Valid := (rCorePressure_PT2_bar >= 1.0) AND (rCorePressure_PT2_bar <= 320.0);
bPt3_Valid := (rCorePressure_PT3_bar >= 1.0) AND (rCorePressure_PT3_bar <= 320.0);

rDeltaP12 := ABS(rCorePressure_PT1_bar - rCorePressure_PT2_bar);
rDeltaP23 := ABS(rCorePressure_PT2_bar - rCorePressure_PT3_bar);
rDeltaP31 := ABS(rCorePressure_PT3_bar - rCorePressure_PT1_bar);

IF bPt1_Valid AND bPt2_Valid AND bPt3_Valid THEN
    IF (rDeltaP12 <= rTmrToleranceLimit_bar) AND (rDeltaP23 <= rTmrToleranceLimit_bar) AND (rDeltaP31 <= rTmrToleranceLimit_bar) THEN
        (* Full 2oo3 Consensus *)
        rVotedCorePressure_bar := (rCorePressure_PT1_bar + rCorePressure_PT2_bar + rCorePressure_PT3_bar) / 3.0;
        iHealthySensorCount    := 3;
        wAlarmWord.2           := FALSE; (* TMR Divergence Clear *)
    ELSIF (rDeltaP12 <= rTmrToleranceLimit_bar) AND (rDeltaP23 > rTmrToleranceLimit_bar) AND (rDeltaP31 > rTmrToleranceLimit_bar) THEN
        (* PT3 Drifting / Failed *)
        rVotedCorePressure_bar := (rCorePressure_PT1_bar + rCorePressure_PT2_bar) / 2.0;
        bPt3_Valid             := FALSE;
        iHealthySensorCount    := 2;
        wAlarmWord.2           := TRUE;  (* Core PT3 Drift Alarm *)
    ELSIF (rDeltaP23 <= rTmrToleranceLimit_bar) AND (rDeltaP12 > rTmrToleranceLimit_bar) AND (rDeltaP31 > rTmrToleranceLimit_bar) THEN
        (* PT1 Drifting / Failed *)
        rVotedCorePressure_bar := (rCorePressure_PT2_bar + rCorePressure_PT3_bar) / 2.0;
        bPt1_Valid             := FALSE;
        iHealthySensorCount    := 2;
        wAlarmWord.2           := TRUE;  (* Core PT1 Drift Alarm *)
    ELSIF (rDeltaP31 <= rTmrToleranceLimit_bar) AND (rDeltaP12 > rTmrToleranceLimit_bar) AND (rDeltaP23 > rTmrToleranceLimit_bar) THEN
        (* PT2 Drifting / Failed *)
        rVotedCorePressure_bar := (rCorePressure_PT1_bar + rCorePressure_PT3_bar) / 2.0;
        bPt2_Valid             := FALSE;
        iHealthySensorCount    := 2;
        wAlarmWord.2           := TRUE;  (* Core PT2 Drift Alarm *)
    ELSE
        (* Total Discrepancy Across All 3 Channels: Median Selection Fallback *)
        IF (rCorePressure_PT1_bar >= rCorePressure_PT2_bar AND rCorePressure_PT1_bar <= rCorePressure_PT3_bar) OR
           (rCorePressure_PT1_bar >= rCorePressure_PT3_bar AND rCorePressure_PT1_bar <= rCorePressure_PT2_bar) THEN
            rVotedCorePressure_bar := rCorePressure_PT1_bar;
        ELSIF (rCorePressure_PT2_bar >= rCorePressure_PT1_bar AND rCorePressure_PT2_bar <= rCorePressure_PT3_bar) OR
              (rCorePressure_PT2_bar >= rCorePressure_PT3_bar AND rCorePressure_PT2_bar <= rCorePressure_PT1_bar) THEN
            rVotedCorePressure_bar := rCorePressure_PT2_bar;
        ELSE
            rVotedCorePressure_bar := rCorePressure_PT3_bar;
        END_IF;
        iHealthySensorCount := 1;
        wAlarmWord.2        := TRUE;
        wAlarmWord.3        := TRUE; (* TMR Incoherence Alarm *)
    END_IF;
ELSIF bPt1_Valid AND bPt2_Valid THEN
    rVotedCorePressure_bar := (rCorePressure_PT1_bar + rCorePressure_PT2_bar) / 2.0;
    iHealthySensorCount    := 2;
    wAlarmWord.2           := TRUE;
ELSIF bPt2_Valid AND bPt3_Valid THEN
    rVotedCorePressure_bar := (rCorePressure_PT2_bar + rCorePressure_PT3_bar) / 2.0;
    iHealthySensorCount    := 2;
    wAlarmWord.2           := TRUE;
ELSIF bPt1_Valid AND bPt3_Valid THEN
    rVotedCorePressure_bar := (rCorePressure_PT1_bar + rCorePressure_PT3_bar) / 2.0;
    iHealthySensorCount    := 2;
    wAlarmWord.2           := TRUE;
ELSIF bPt1_Valid THEN
    rVotedCorePressure_bar := rCorePressure_PT1_bar;
    iHealthySensorCount    := 1;
    wAlarmWord.3           := TRUE;
ELSIF bPt2_Valid THEN
    rVotedCorePressure_bar := rCorePressure_PT2_bar;
    iHealthySensorCount    := 1;
    wAlarmWord.3           := TRUE;
ELSIF bPt3_Valid THEN
    rVotedCorePressure_bar := rCorePressure_PT3_bar;
    iHealthySensorCount    := 1;
    wAlarmWord.3           := TRUE;
ELSE
    (* Total Pressure Sensor Loss: Safe Hold & Critical Alarm *)
    rVotedCorePressure_bar := 90.0;
    iHealthySensorCount    := 0;
    wAlarmWord.3           := TRUE;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: DIGITAL SIGNAL FILTERING, FLUID DYNAMICS & CROSS VISCOSITY MODELING
   --------------------------------------------------------------------------------------------------------------------- *)
(* First-order recursive low-pass filters (alpha = 0.20 on pressure, alpha = 0.10 on thermal signals) *)
rCorePress_Filt    := (0.80 * rCorePress_Filt) + (0.20 * rVotedCorePressure_bar);
rSheathPress_Filt  := (0.80 * rSheathPress_Filt) + (0.20 * rSheathPressure_bar);
rCoreTemp_Filt     := (0.90 * rCoreTemp_Filt) + (0.10 * rCoreMeltTemp_DegC);
rSheathTemp_Filt   := (0.90 * rSheathTemp_Filt) + (0.10 * rSheathMeltTemp_DegC);
rBarrierTemp_Filt  := (0.90 * rBarrierTemp_Filt) + (0.10 * rDieThermalBarrierTemp_DegC);

(* Peak Core Temperature Tracking for cGMP Batch Records *)
IF rCoreTemp_Filt > rPeakCoreMeltTempRecorded_DegC THEN
    rPeakCoreMeltTempRecorded_DegC := rCoreTemp_Filt;
END_IF;

(* Absolute Temperatures in Kelvin *)
rCoreTemp_K   := rCoreTemp_Filt + 273.15;
rSheathTemp_K := rSheathTemp_Filt + 273.15;

(* Arrhenius Shift Factors: a_T = exp( (E_a / R) * (1/T - 1/T_ref) ) *)
rCore_ShiftFactor   := EXP(rCore_Ea_Over_R * ((1.0 / rCoreTemp_K) - (1.0 / rCore_Tref_K)));
rSheath_ShiftFactor := EXP(rSheath_Ea_Over_R * ((1.0 / rSheathTemp_K) - (1.0 / rSheath_Tref_K)));

(* Clamp shift factors to prevent floating point numerical overflows under extreme thermal transients *)
IF rCore_ShiftFactor < 0.10 THEN rCore_ShiftFactor := 0.10; ELSIF rCore_ShiftFactor > 10.0 THEN rCore_ShiftFactor := 10.0; END_IF;
IF rSheath_ShiftFactor < 0.10 THEN rSheath_ShiftFactor := 0.10; ELSIF rSheath_ShiftFactor > 10.0 THEN rSheath_ShiftFactor := 10.0; END_IF;

(* Apparent Shear Rate Calculations from Gravimetric Feeder Mass Flows:
     Volumetric Flow Q_vol = (Feed_g_per_min / 60) * 1e-6 / Density_kg_per_m3  [m3/s]
*)
IF rCoreGravimetricFeed_gpmin > 0.1 THEN
    rCoreShearRate_s1 := (4.0 * ((rCoreGravimetricFeed_gpmin / 60.0) * 1.0E-6 / rPolymerDensity_kgm3)) /
                         (3.14159 * (rCoreOrificeRadius_m * rCoreOrificeRadius_m * rCoreOrificeRadius_m));
ELSE
    rCoreShearRate_s1 := 1.0;
END_IF;

IF rSheathGravimetricFeed_gpmin > 0.1 THEN
    rSheathShearRate_s1 := (6.0 * ((rSheathGravimetricFeed_gpmin / 60.0) * 1.0E-6 / rPolymerDensity_kgm3)) /
                           (3.14159 * (2.0 * rSheathMeanRadius_m) * (rSheathAnnulusGap_m * rSheathAnnulusGap_m));
ELSE
    rSheathShearRate_s1 := 1.0;
END_IF;

(* Bound Shear Rates to Valid Non-Newtonian Domain *)
IF rCoreShearRate_s1 < 0.5 THEN rCoreShearRate_s1 := 0.5; ELSIF rCoreShearRate_s1 > 2500.0 THEN rCoreShearRate_s1 := 2500.0; END_IF;
IF rSheathShearRate_s1 < 0.5 THEN rSheathShearRate_s1 := 0.5; ELSIF rSheathShearRate_s1 > 2500.0 THEN rSheathShearRate_s1 := 2500.0; END_IF;

(* Cross Model Dynamic Viscosity Evaluation:
     eta(gamma, T) = (eta_0 * a_T) / ( 1 + (lambda * a_T * gamma)^(1 - n) )
*)
rCoreViscosity_Pas := (rCore_Eta0_Ref * rCore_ShiftFactor) /
                      (1.0 + EXP((1.0 - rCore_PowerLaw_n) * LN(1.0 + (rCore_Cross_Lambda * rCore_ShiftFactor * rCoreShearRate_s1))));

rSheathViscosity_Pas := (rSheath_Eta0_Ref * rSheath_ShiftFactor) /
                        (1.0 + EXP((1.0 - rSheath_PowerLaw_n) * LN(1.0 + (rSheath_Cross_Lambda * rSheath_ShiftFactor * rSheathShearRate_s1))));

(* Prevent Division by Zero *)
IF rSheathViscosity_Pas < 50.0 THEN rSheathViscosity_Pas := 50.0; END_IF;
IF rCoreViscosity_Pas < 50.0 THEN rCoreViscosity_Pas := 50.0; END_IF;

rEstimatedViscosityRatio := rCoreViscosity_Pas / rSheathViscosity_Pas;

(* Micro-Die Thermal Segregation Gradient across Ceramic Sleeve *)
rCoreSheathThermalDelta_DegC := rSheathTemp_Filt - rCoreTemp_Filt;

(* Mean Residence Time in Core Hot Zone: Volume / Q_vol *)
IF rCoreGravimetricFeed_gpmin > 0.5 THEN
    rCoreResidenceTime_s := (2.85E-6 * rPolymerDensity_kgm3 * 60.0) / (rCoreGravimetricFeed_gpmin * 1.0E-3);
ELSE
    rCoreResidenceTime_s := 999.0;
END_IF;

(* Viscosity Balance Status Evaluation (Acceptable Range: 0.88 .. 1.15) *)
bViscosityBalanced := (rEstimatedViscosityRatio >= 0.88) AND (rEstimatedViscosityRatio <= 1.15);

(* Thermal Segregation Status Evaluation (Target: 38.0 +/- 3.5 deg C) *)
bThermalSegregationOk := (rCoreSheathThermalDelta_DegC >= 34.5) AND (rCoreSheathThermalDelta_DegC <= 42.0);

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: STATE-SPACE ERROR FORMULATION & MODEL PREDICTIVE CONTROL TRIMS
   --------------------------------------------------------------------------------------------------------------------- *)
(* Formulate discrete state deviation vector x(k) *)
rX_State1_CorePErr       := rCorePress_Filt - rCorePressureSetpoint_bar;
rX_State2_SheathPErr     := rSheathPress_Filt - rSheathPressureSetpoint_bar;
rX_State3_ViscLogErr     := LN(rEstimatedViscosityRatio / rTargetViscosityRatio);
rX_State4_ThermalGradErr := rCoreSheathThermalDelta_DegC - rTargetThermalSegregation_DegC;

(* Multivariable Feedback Control Law: delta_u = - (K_mpc * x) *)
rDeltaU1_CorePump := - ( (rK11 * rX_State1_CorePErr) + (rK12 * rX_State2_SheathPErr) +
                         (rK13 * rX_State3_ViscLogErr) + (rK14 * rX_State4_ThermalGradErr) );

rDeltaU2_SheathPump := - ( (rK21 * rX_State1_CorePErr) + (rK22 * rX_State2_SheathPErr) +
                           (rK23 * rX_State3_ViscLogErr) + (rK24 * rX_State4_ThermalGradErr) );

rDeltaU3_SheathDieHeat := - ( (rK31 * rX_State1_CorePErr) + (rK32 * rX_State2_SheathPErr) +
                              (rK33 * rX_State3_ViscLogErr) + (rK34 * rX_State4_ThermalGradErr) );

rDeltaU4_BarrierAirCool := - ( (rK41 * rX_State1_CorePErr) + (rK42 * rX_State2_SheathPErr) +
                               (rK43 * rX_State3_ViscLogErr) + (rK44 * rX_State4_ThermalGradErr) );

(* Saturation Capping on Incremental Actuator Trims *)
IF rDeltaU1_CorePump > 4.5 THEN rDeltaU1_CorePump := 4.5; ELSIF rDeltaU1_CorePump < -4.5 THEN rDeltaU1_CorePump := -4.5; END_IF;
IF rDeltaU2_SheathPump > 5.5 THEN rDeltaU2_SheathPump := 5.5; ELSIF rDeltaU2_SheathPump < -5.5 THEN rDeltaU2_SheathPump := -5.5; END_IF;
IF rDeltaU3_SheathDieHeat > 15.0 THEN rDeltaU3_SheathDieHeat := 15.0; ELSIF rDeltaU3_SheathDieHeat < -15.0 THEN rDeltaU3_SheathDieHeat := -15.0; END_IF;
IF rDeltaU4_BarrierAirCool > 20.0 THEN rDeltaU4_BarrierAirCool := 20.0; ELSIF rDeltaU4_BarrierAirCool < -20.0 THEN rDeltaU4_BarrierAirCool := -20.0; END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: ISA-88 CONTINUOUS FINITE STATE MACHINE (CO-EXTRUSION PROCESS SEQUENCER)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_STANDBY_PURGE: Hardware validation, heaters at standby soak, pumps stationary *)
        bSystemReady                    := FALSE;
        bDegradedModeActive             := FALSE;
        rCoreMeltPumpSpeed_rpm          := 0.0;
        rSheathMeltPumpSpeed_rpm        := 0.0;
        rCoreDieHeaterPower_Pct         := 25.0;  (* Gentle pre-warming *)
        rSheathDieHeaterPower_Pct       := 35.0;
        rDieThermalSegregationHeat_Pct  := 10.0;
        rMicroAirCoolingValve_Pct       := 0.0;
        wSystemStatusWord               := 16#0001;

        tonStartupSoak(IN := bMasterEnable, PT := T#12S);
        IF tonStartupSoak.Q THEN
            tonStartupSoak(IN := FALSE);
            IF (iHealthySensorCount >= 2) AND (rSheathOuterDieTemp_DegC >= 140.0) THEN
                iState := 10; (* Advance to Thermal Soak Segregation Init *)
            ELSE
                wAlarmWord.4 := TRUE; (* Temperature or Sensor Not Ready *)
            END_IF;
        END_IF;

    10: (* STATE_THERMAL_SOAK_SEGREGATION_INIT: Establish 38 deg C gradient across ceramic micro-barrier *)
        bSystemReady                    := FALSE;
        bDegradedModeActive             := FALSE;
        rCoreMeltPumpSpeed_rpm          := 0.0;
        rSheathMeltPumpSpeed_rpm        := 0.0;
        rCoreDieHeaterPower_Pct         := 45.0;
        rSheathDieHeaterPower_Pct       := 70.0;
        rDieThermalSegregationHeat_Pct  := 30.0;
        rMicroAirCoolingValve_Pct       := 15.0; (* Active vortex barrier establishing gradient *)
        wSystemStatusWord               := 16#0010;

        (* Check thermal segregation barrier establishment *)
        IF (rCoreSheathThermalDelta_DegC >= 32.0) AND (rCoreSheathThermalDelta_DegC <= 44.0) AND
           (rCoreTemp_Filt >= 130.0) AND (rCoreTemp_Filt <= 138.0) AND
           (rSheathTemp_Filt >= 168.0) AND (rSheathTemp_Filt <= 178.0) THEN
            tonMeltStabilization(IN := TRUE, PT := T#10S);
            IF tonMeltStabilization.Q THEN
                tonMeltStabilization(IN := FALSE);
                iState := 20; (* Advance to Melt Synchronization *)
            END_IF;
        ELSE
            tonMeltStabilization(IN := FALSE);
        END_IF;

        IF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    20: (* STATE_POLYMER_MELT_PRIME_SYNC: Synchronized gear pump priming to fill micro-die channels *)
        bSystemReady                    := TRUE;
        bDegradedModeActive             := FALSE;
        wSystemStatusWord               := 16#0020;

        (* Ramped initial displacement to fill micro-channels without pressure surge *)
        rCoreMeltPumpSpeed_rpm          := 6.0;
        rSheathMeltPumpSpeed_rpm        := 8.0;
        rCoreDieHeaterPower_Pct         := 50.0;
        rSheathDieHeaterPower_Pct       := 65.0;
        rDieThermalSegregationHeat_Pct  := 28.0;
        rMicroAirCoolingValve_Pct       := 20.0;

        (* Transition to closed loop once pressure builds to steady threshold *)
        IF (rVotedCorePressure_bar >= 40.0) AND (rSheathPress_Filt >= 45.0) THEN
            IF bAutoMpcEnable THEN
                iState := 30; (* Engage Full Closed-Loop MPC *)
            END_IF;
        END_IF;

        IF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    30: (* STATE_FULL_COEXTRUSION_MPC_ACTIVE: Full closed-loop multivariable regulation *)
        bSystemReady        := TRUE;
        bDegradedModeActive := (iHealthySensorCount < 3);
        wSystemStatusWord   := 16#0030;

        (* Apply Multivariable Predictive Actuator Updates *)
        rCoreMeltPumpSpeed_rpm   := rCorePumpNominal_rpm + rDeltaU1_CorePump;
        rSheathMeltPumpSpeed_rpm := rSheathPumpNominal_rpm + rDeltaU2_SheathPump;

        (* Core pin thermal maintenance *)
        rCoreDieHeaterPower_Pct  := 48.0 - (rX_State4_ThermalGradErr * 0.85);

        (* Sheath ring thermal modulation *)
        rSheathDieHeaterPower_Pct := rSheathDieHeatNominal_Pct + rDeltaU3_SheathDieHeat;

        (* Micro-die barrier guard heater and active air cooling modulation *)
        rDieThermalSegregationHeat_Pct := 35.0 + (rDeltaU4_BarrierAirCool * 0.40);
        rMicroAirCoolingValve_Pct      := rBarrierAirNominal_Pct + rDeltaU4_BarrierAirCool;

        (* Clamping Actuator Absolute Limits *)
        IF rCoreMeltPumpSpeed_rpm < 2.0 THEN rCoreMeltPumpSpeed_rpm := 2.0; ELSIF rCoreMeltPumpSpeed_rpm > 55.0 THEN rCoreMeltPumpSpeed_rpm := 55.0; END_IF;
        IF rSheathMeltPumpSpeed_rpm < 3.0 THEN rSheathMeltPumpSpeed_rpm := 3.0; ELSIF rSheathMeltPumpSpeed_rpm > 55.0 THEN rSheathMeltPumpSpeed_rpm := 55.0; END_IF;
        IF rCoreDieHeaterPower_Pct < 0.0 THEN rCoreDieHeaterPower_Pct := 0.0; ELSIF rCoreDieHeaterPower_Pct > 90.0 THEN rCoreDieHeaterPower_Pct := 90.0; END_IF;
        IF rSheathDieHeaterPower_Pct < 10.0 THEN rSheathDieHeaterPower_Pct := 10.0; ELSIF rSheathDieHeaterPower_Pct > 95.0 THEN rSheathDieHeaterPower_Pct := 95.0; END_IF;
        IF rMicroAirCoolingValve_Pct < 0.0 THEN rMicroAirCoolingValve_Pct := 0.0; ELSIF rMicroAirCoolingValve_Pct > 100.0 THEN rMicroAirCoolingValve_Pct := 100.0; END_IF;

        (* Supervisory Event Detection & Adaptive State Transitions *)
        IF (rEstimatedViscosityRatio < 0.82) OR (rEstimatedViscosityRatio > 1.25) THEN
            tonViscosityFaultDebounce(IN := TRUE, PT := T#3S);
            IF tonViscosityFaultDebounce.Q THEN
                tonViscosityFaultDebounce(IN := FALSE);
                iState := 40; (* Severe Viscosity Imbalance Condition *)
            END_IF;
        ELSE
            tonViscosityFaultDebounce(IN := FALSE);
        END_IF;

        IF (rCoreSheathThermalDelta_DegC < 30.0) OR (rCoreSheathThermalDelta_DegC > 48.0) THEN
            tonThermalFaultDebounce(IN := TRUE, PT := T#4S);
            IF tonThermalFaultDebounce.Q THEN
                tonThermalFaultDebounce(IN := FALSE);
                iState := 50; (* Thermal Barrier Compromise *)
            END_IF;
        ELSE
            tonThermalFaultDebounce(IN := FALSE);
        END_IF;

        IF iHealthySensorCount <= 1 THEN
            iState := 60; (* Degraded Sensor Mode *)
        END_IF;

        IF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    40: (* STATE_VISCOSITY_IMBALANCE_COMPENSATION: Aggressive shear/temperature trim to re-balance melts *)
        bSystemReady            := TRUE;
        bDegradedModeActive     := TRUE;
        wSystemStatusWord       := 16#0040;
        wAlarmWord.5            := TRUE; (* Viscosity Mismatch Excursion *)
        udiViscosityViolationCycles := udiViscosityViolationCycles + 1;

        IF rEstimatedViscosityRatio < 0.88 THEN
            (* Core melt is too fluid relative to sheath: cool core slightly, raise sheath temp, reduce sheath pump *)
            rSheathDieHeaterPower_Pct := rSheathDieHeaterPower_Pct + 2.5;
            rCoreDieHeaterPower_Pct   := rCoreDieHeaterPower_Pct - 1.5;
            rSheathMeltPumpSpeed_rpm  := rSheathMeltPumpSpeed_rpm - 0.5;
            rCoreMeltPumpSpeed_rpm    := rCoreMeltPumpSpeed_rpm + 0.3;
        ELSIF rEstimatedViscosityRatio > 1.15 THEN
            (* Core melt is too viscous relative to sheath: warm core carefully, lower sheath temp *)
            IF rCoreTemp_Filt < 139.0 THEN
                rCoreDieHeaterPower_Pct := rCoreDieHeaterPower_Pct + 1.2;
            END_IF;
            rSheathDieHeaterPower_Pct := rSheathDieHeaterPower_Pct - 2.0;
            rCoreMeltPumpSpeed_rpm    := rCoreMeltPumpSpeed_rpm - 0.4;
            rSheathMeltPumpSpeed_rpm  := rSheathMeltPumpSpeed_rpm + 0.4;
        END_IF;

        (* Clamp boundaries *)
        IF rCoreDieHeaterPower_Pct > 65.0 THEN rCoreDieHeaterPower_Pct := 65.0; END_IF;
        IF rSheathDieHeaterPower_Pct > 95.0 THEN rSheathDieHeaterPower_Pct := 95.0; END_IF;

        (* Return to normal once viscosity ratio restored within 0.92 .. 1.10 *)
        IF (rEstimatedViscosityRatio >= 0.92) AND (rEstimatedViscosityRatio <= 1.10) THEN
            wAlarmWord.5 := FALSE;
            iState       := 30;
        END_IF;

    50: (* STATE_THERMAL_BARRIER_FAULT_CONTAINMENT: Micro-die insulation degradation recovery *)
        bSystemReady                := TRUE;
        bDegradedModeActive         := TRUE;
        wSystemStatusWord           := 16#0050;
        wAlarmWord.6                := TRUE; (* Thermal Segregation Collapse Alarm *)
        udiThermalViolationCycles   := udiThermalViolationCycles + 1;

        (* Maximize thermal barrier protection: blast vortex cooling air and bias sheath heat *)
        IF rCoreSheathThermalDelta_DegC < 32.0 THEN
            rMicroAirCoolingValve_Pct      := 85.0; (* Intensify air barrier *)
            rDieThermalSegregationHeat_Pct := 15.0;
            rSheathDieHeaterPower_Pct      := 85.0;
            rCoreDieHeaterPower_Pct        := 30.0;
        ELSIF rCoreSheathThermalDelta_DegC > 46.0 THEN
            rMicroAirCoolingValve_Pct      := 5.0;  (* Reduce excessive cooling *)
            rDieThermalSegregationHeat_Pct := 50.0;
        END_IF;

        (* Recovered when delta-T restored to 35.0 .. 41.0 deg C *)
        IF (rCoreSheathThermalDelta_DegC >= 35.0) AND (rCoreSheathThermalDelta_DegC <= 41.0) THEN
            wAlarmWord.6 := FALSE;
            iState       := 30;
        END_IF;

    60: (* STATE_DEGRADED_PRESSURE_FALLBACK: Operating on single validated pressure channel *)
        bSystemReady        := TRUE;
        bDegradedModeActive := TRUE;
        wSystemStatusWord   := 16#0060;
        wAlarmWord.7        := TRUE; (* Degraded 1oo1 Operation *)

        (* Limit throughput and freeze aggressive MPC trims; lock to robust feedforward ratios *)
        rCoreMeltPumpSpeed_rpm   := rCorePumpNominal_rpm * 0.85;
        rSheathMeltPumpSpeed_rpm := rSheathPumpNominal_rpm * 0.85;

        rCoreDieHeaterPower_Pct        := 45.0;
        rSheathDieHeaterPower_Pct      := 62.0;
        rDieThermalSegregationHeat_Pct := 32.0;
        rMicroAirCoolingValve_Pct      := 25.0;

        (* Restoration to 2oo3 or 2oo2 resumes full MPC state *)
        IF iHealthySensorCount >= 2 THEN
            wAlarmWord.7 := FALSE;
            iState       := 30;
        END_IF;

        IF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    99: (* STATE_CRITICAL_EMERGENCY_DEPRESSURIZE: Immediate depressurization & thermal safe-park *)
        bSystemReady                   := FALSE;
        bDegradedModeActive            := FALSE;
        rCoreMeltPumpSpeed_rpm         := 0.0;
        rSheathMeltPumpSpeed_rpm       := 0.0;
        rCoreDieHeaterPower_Pct        := 0.0;
        rSheathDieHeaterPower_Pct      := 0.0;
        rDieThermalSegregationHeat_Pct := 0.0;
        rMicroAirCoolingValve_Pct      := 100.0; (* Full cooling to prevent core polymer thermal baking *)
        wSystemStatusWord              := 16#9999;
        wAlarmWord.8                   := TRUE;  (* Emergency Depressurization Latch *)

        (* Acknowledge and safe reset condition *)
        IF bSafetyInterlockOk AND NOT bMasterEnable AND (rVotedCorePressure_bar < 5.0) THEN
            wAlarmWord.8 := FALSE;
            iState       := 0;
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 6: ISA-18.2 SECONDARY ALARMS, MECHANICAL TORQUE MONITORING & DIE OVERPRESSURE TRIPS
   --------------------------------------------------------------------------------------------------------------------- *)
(* Core Extruder Barrel / Gear Pump Overpressure Trip (Trip Threshold: 260 bar) *)
IF rVotedCorePressure_bar >= 260.0 THEN
    wAlarmWord.9 := TRUE; (* Core Overpressure Hazard Trip *)
    iState       := 99;
ELSE
    wAlarmWord.9 := FALSE;
END_IF;

(* Sheath Melt Pump Overpressure Trip (Trip Threshold: 280 bar) *)
IF rSheathPress_Filt >= 280.0 THEN
    wAlarmWord.10 := TRUE; (* Sheath Overpressure Hazard Trip *)
    iState        := 99;
ELSE
    wAlarmWord.10 := FALSE;
END_IF;

(* Extruder Motor Mechanical Torque Overload (Cold Slug / Polymer Jam Interlock) *)
IF (rCoreExtruderTorque_Nm >= 105.0) OR (rSheathExtruderTorque_Nm >= 110.0) THEN
    wAlarmWord.11 := TRUE; (* Motor Drive Torque Overload *)
    iState        := 99;
ELSE
    wAlarmWord.11 := FALSE;
END_IF;

(* Micro-Die Confluence Exit Pressure Disruption (Delamination / Blockage) *)
IF (rDieConfluencePressure_bar > 185.0) OR (rDieConfluencePressure_bar < 15.0 AND iState = 30) THEN
    wAlarmWord.12 := TRUE; (* Confluence Anomaly *)
ELSE
    wAlarmWord.12 := FALSE;
END_IF;

END_FUNCTION_BLOCK
